<?php namespace App\Http\Middleware; use Closure; use Illuminate\Http\Request; use Symfony\Component\HttpFoundation\Response; class EnsureAccountIsActive { public function handle(Request $request, Closure $next): Response { $u=$request->user(); if ($u?->is_blocked) { auth()->logout(); return redirect()->route('login')->withErrors(['email'=>'Учётная запись заблокирована.']); } if (!$u?->hasActiveSubscription()) return redirect()->route('subscription.create')->with('warning','Требуется активная подписка.'); return $next($request); } }
